def make_clip(path: str, source: str, tone: int, seconds: int, title: str) -> None:
    font = "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"
    # drawtext escaping: ':' and ',' are filtergraph separators, quotes end the value
    text = title.replace("\\", "").replace("'", "").replace(":", "\\:").replace(",", "\\,")[:40]
    vf = (
        f"drawtext=fontfile={font}:text='{text}':fontcolor=white:fontsize=44:"
        "box=1:boxcolor=black@0.45:boxborderw=18:x=(w-text_w)/2:y=h-text_h-60"
    )
    subprocess.run(
        [
            "ffmpeg",
            "-nostdin",
            "-loglevel",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            source,  # infinite source, cut by -t below
            "-f",
            "lavfi",
            "-i",
            f"sine=frequency={tone}:duration={seconds}:sample_rate=44100",
            "-vf",
            vf,
            "-t",
            str(seconds),
            "-c:v",
            "libx264",
            "-preset",
            "ultrafast",
            "-pix_fmt",
            "yuv420p",
            "-c:a",
            "aac",
            "-shortest",
            path,
        ],
        check=True,
    )


async def main() -> int:
    s = get_settings()
    password = os.environ.get("DEMO_PASSWORD", "")
    if len(password) < 8:
        print("seed: DEMO_PASSWORD is not set (run scripts/gen_env.sh)", file=sys.stderr)
        return 1

    async with SessionLocal() as session:
        if await users_repo.get_user_by_username(session, "alice") is not None:
            print("seed: demo data already present, nothing to do")
            return 0

    users: dict[str, User] = {}
    client = auth_service.ClientInfo(ip=None, user_agent="seed")
    async with SessionLocal() as session:
        for username, title, role, about in USERS:
            data = RegisterIn(
                email=f"{username}@vidora.example.com",
                username=username,
                password=password,
                channel_title=title,
            )
            tokens = await auth_service.register(session, data, client, role)
            users[username] = tokens.user
            await channel_service.update_own(session, tokens.user, ChannelUpdate(description=about))
    print(f"seed: {len(users)} users created")

    now = datetime.now(UTC)
    video_ids: dict[str, uuid.UUID] = {}
    with tempfile.TemporaryDirectory(prefix="vidora-seed-") as tmp:
        for i, (owner, title, desc, tags, source, tone, secs, vis) in enumerate(VIDEOS, start=1):
            path = os.path.join(tmp, f"{i}.mp4")
            make_clip(path, source, tone, secs, title)
            async with SessionLocal() as session:
                video = Video(
                    channel_id=users[owner].channel.id,
                    title=title,
                    description=desc,
                    visibility=Visibility(vis),
                    status=VideoStatus.UPLOADED,
                )
                session.add(video)
                await session.flush()
                key = f"uploads/{video.id}/original"
                await asyncio.to_thread(storage.upload_file_sync, path, s.bucket_raw, key, "video/mp4")
                session.add(
                    VideoFile(
                        video_id=video.id,
                        kind=FileKind.ORIGINAL,
                        quality="original",
                        bucket=s.bucket_raw,
                        object_key=key,
                        mime_type="video/mp4",
                        size_bytes=os.path.getsize(path),
                    )
                )
                await videos_repo.set_tags(session, video.id, tags)
                await session.commit()
                video_ids[title] = video.id
            await process_video_now(video_ids[title])
            print(f"seed: video {i}/{len(VIDEOS)} ready: {title}")

    async with SessionLocal() as session:
        # Spread publication dates and give demo view counters (counters only, no fake view rows).
        for i, vid in enumerate(video_ids.values()):
            await session.execute(
                update(Video)
                .where(Video.id == vid)
                .values(
                    published_at=now - timedelta(days=rnd.randint(0, 60), hours=rnd.randint(0, 23)),
                    views_count=rnd.choice([87, 412, 1_530, 12_400, 57_800, 230_000]) + i,
                )
            )
        await session.commit()

    async with SessionLocal() as session:
        fresh = {u: await users_repo.get_user(session, users[u].id) for u in users}
        viewers = [fresh[u] for u in ("alice", "bob", "carol", "dave", "moderator")]
        public_ids = [
            vid
            for (o, t, *_rest, vis), vid in zip(VIDEOS, video_ids.values(), strict=True)
            if vis == "public"
        ]

        for creator in ("alice", "bob", "carol", "dave"):
            for viewer in viewers:
                if viewer.username != creator and rnd.random() < 0.75:
                    await channel_service.set_subscription(session, viewer, fresh[creator].channel.id, True)

        for vid in public_ids:
            for viewer in viewers:
                roll = rnd.random()
                if roll < 0.6:
                    await video_service.react(session, vid, viewer, 1)
                elif roll < 0.68:
                    await video_service.react(session, vid, viewer, -1)
            for _ in range(rnd.randint(1, 4)):
                author = rnd.choice(viewers)
                top = await comment_service.create(session, vid, author, CommentIn(body=rnd.choice(COMMENTS)))
                if rnd.random() < 0.5:
                    replier = rnd.choice(viewers)
                    await comment_service.create(
                        session, vid, replier, CommentIn(body=rnd.choice(REPLIES), parent_id=top.id)
                    )

        # Private video: alice shares her draft with bob only.
        draft = video_ids["Черновик: монтаж поездки"]
        await video_service.add_grant(session, draft, fresh["alice"], "bob")

        # Playlists
        host = "localhost"
        best = await playlist_service.create(
            session,
            fresh["alice"],
            PlaylistCreate(title="Лучшие места", description="Куда поехать летом"),
            host,
        )
        for t in (
            "Закат над горами: таймлапс за 10 секунд",
            "Озеро на рассвете",
            "Прогулка по старому городу",
        ):
            await playlist_service.add_video(session, best.id, fresh["alice"], video_ids[t])
        dev = await playlist_service.create(
            session, fresh["bob"], PlaylistCreate(title="Бэкенд для начинающих"), host
        )
        for t in ("Пишем REST API на FastAPI за 10 минут", "Как работает видеостриминг: Range-запросы"):
            await playlist_service.add_video(session, dev.id, fresh["bob"], video_ids[t])

        # Something for the moderation queue
        await moderation_service.create_report(
            session,
            fresh["carol"],
            ReportIn(
                video_id=video_ids["Lo-fi для учёбы"], reason="copyright", details="Похоже на чужой трек"
            ),
        )
        some_comment = await session.scalar(
            select(Comment.id).where(Comment.author_id != fresh["dave"].id).limit(1)
        )
        if some_comment:
            await moderation_service.create_report(
                session, fresh["dave"], ReportIn(comment_id=some_comment, reason="spam", details="")
            )

    await engine.dispose()
    print(
        f"seed: done: {len(USERS)} users, {len(VIDEOS)} videos, comments, likes, subscriptions, "
        "2 playlists, 2 open reports"
    )
    return 0


if __name__ == "__main__":
    sys.exit(asyncio.run(main()))
